@include('user.brand-kits.styles')
<style>
.ms-page{width:100%;color:var(--text-primary)}.ms-tabs{display:flex;gap:8px;overflow-x:auto;white-space:nowrap;margin:22px 0;padding-bottom:5px}.ms-tabs a{padding:11px 20px;border-radius:12px;color:var(--text-muted);border:1px solid var(--border-glass)}.ms-tabs a[aria-current=page]{background:var(--accent,#3454ef);color:#fff;border-color:transparent}.ms-card{border:1px solid var(--border-glass);border-radius:22px;padding:24px;background:var(--bg-card);min-width:0}.ms-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:20px}.ms-kicker{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--text-muted)}.ms-next{background:linear-gradient(125deg,#3454ef0d,#8b5cf60a);border:1px solid #3454ef26;border-radius:18px;padding:22px;margin:20px 0}.ms-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,1fr);gap:24px;align-items:start}.ms-preview{position:sticky;top:100px}.ms-legacy{max-width:none!important;width:100%;padding:0!important;color:var(--text-primary)}.ms-legacy [class*="text-white"]{color:var(--text-primary)}.ms-legacy [class*="text-white/"]{color:var(--text-muted)}.ms-legacy [class*="border-white/"]{border-color:var(--border-glass)}.ms-legacy [class*="bg-white/"]{background:var(--bg-card)}.ms-legacy input,.ms-legacy select,.ms-legacy textarea{background:var(--bg-glass-input);color:var(--text-primary);border-color:var(--border-glass)}.ms-legacy [class*="bg-primary-5"]{color:#fff}.ms-legacy .ms-tabs a[aria-current=page]{color:#fff}.ms-page .bk-check[aria-pressed=true]{border-color:var(--accent,#3454ef);background:color-mix(in srgb,var(--accent,#3454ef) 8%,transparent)}.ms-status{display:inline-flex;padding:5px 10px;border-radius:999px;background:var(--bg-glass-hover);font-size:12px;color:var(--text-muted)}.ms-phone{background:#101322;border:9px solid #08090d;border-radius:36px;padding:22px 14px;box-shadow:0 15px 40px #0002;max-width:340px;margin:auto;min-height:440px;color:#f8fafc}.ms-phone .sample{padding:15px;border:1px solid #ffffff25;border-radius:13px;margin-top:15px;background:#ffffff08}.ms-phone .sample-primary{background:#3454ef;color:#fff}.ms-legacy .ms-kicker{color:var(--text-muted)}@media(max-width:1000px){.ms-grid{grid-template-columns:1fr}.ms-preview{position:static}}
</style>
